const statusMap = {
  lead_interested: "Interested",
  lead_meeting_booked: "Meeting Booked",
  reply_received: "Replied",
  auto_reply_received: "Auto Reply",
  negative_reply: "Not Interested",
  lead_meeting_completed: "Meeting Completed",
  campaign_completed_for_lead_without_reply: "No Reply",
  campaign_started: "Campaign Started",
  campaign_paused: "Campaign Paused",
  campaign_completed: "Campaign Completed",
  email_bounced: "Bounced",
  email_open: "Opened",
  email_reply: "Replied",
};

return $input.all().map(item => {
  const body = item.json;

  // Normalize email
  const leadEmail = $input.first().json.body.lead_email || null;

  // Normalize event type
  const eventType = $input.first().json.body.event_type || null;

  // Map status safely in plain JS
  let mappedStatus = "Unknown";
  if (eventType && statusMap.hasOwnProperty(eventType)) {
    mappedStatus = statusMap[eventType];
  } else if (eventType) {
    mappedStatus = eventType;
  }

  const timestamp = body.timestamp_created || body.timestamp || new Date().toISOString();

  return {
    json: {
      leadEmail,
      eventType,
      mappedStatus,
      timestamp,
      raw: body
    }
  };
});
